type S2CTagQuery struct {
	TransactionId ns.VarInt
	Tag           nbt.Tag
}

func (p *S2CTagQuery) Read(buf *ns.PacketBuffer) error {
	var err error
	_ = err
	if p.TransactionId, err = buf.ReadVarInt(); err != nil {
		return err
	}
	{
		nr := nbt.NewReaderFrom(buf.Reader())
		if p.Tag, _, err = nr.ReadTag(true); err != nil {
			return err
		}
	}
	return nil
}

func (p *S2CTagQuery) Write(buf *ns.PacketBuffer) error {
	var err error
	_ = err
	if err = buf.WriteVarInt(p.TransactionId); err != nil {
		return err
	}
	{
		d, e := nbt.EncodeNetwork(p.Tag)
		if e != nil {
			return e
		}
		if _, err = buf.Write(d); err != nil {
			return err
		}
	}
	return nil
}

